export const events = {
	appearanceCorners: (callback: (payload: Corners) => void) => listen<Corners>("appearance.corners", callback),
	appearanceMotion: (callback: (payload: Motion) => void) => listen<Motion>("appearance.motion", callback),
	appearanceTypography: (callback: (payload: Typography) => void) => listen<Typography>("appearance.typography", callback),
	kestrelPalette: (callback: (payload: Palette) => void) => listen<Palette>("kestrel.palette", callback),
	magpieFolder: (callback: (payload: Listing) => void) => listen<Listing>("magpie.folder", callback),
	magpieMedia: (callback: (payload: MediaAction) => void) => listen<MediaAction>("magpie.media", callback),
	magpieThumbnails: (callback: (payload: ThumbnailBatch) => void) => listen<ThumbnailBatch>("magpie.thumbnails", callback),
};

export type App = {
	id: string,
	name: string,
	icon: string | null,
};

export type AppIconStyle = "default" | "tinted" | "clear";

export type AppIcons = {
	style: AppIconStyle,
	glyphs: string,
	tinted: IconPaint,
	clear: IconPaint,
};

export type AppState = {
	launchPaths: string[],
} & Appearance;

export type Appearance = {
	palette: Palette | null,
	typography: Typography,
	motion: Motion,
	corners: Corners,
	locale: Locale,
};

export type Coordinates = {
	latitude: number,
	longitude: number,
	altitude: number | null,
};

export type Corners = "rounded" | "square";

export type Cue = {
	start: number,
	end: number,
	text: string,
};

export type Folder = {
	path: string,
	name: string,
};

export type FontAxis = {
	tag: string,
	name: string,
	min: number,
	default: number,
	max: number,
};

export type FontFace = {
	index: number,
	fullName: string | null,
	weight: number,
	italic: boolean,
	version: string | null,
	designer: string | null,
	manufacturer: string | null,
	license: string | null,
	licenseUrl: string | null,
	copyright: string | null,
	sample: string | null,
	glyphs: number,
	monospace: boolean,
	characters: ([number, number])[],
	axes: FontAxis[],
	instances: FontInstance[],
} & FontIdentity;

export type FontFile = {
	format: string,
	faces: FontFace[],
};

export type FontIdentity = {
	family: string,
	style: string,
	postscript: string | null,
};

export type FontInstance = {
	name: string,
	coordinates: ([string, number])[],
};

export type FontStatus = "missing" | "system" | "user";

export type IconPaint = {
	plate: string,
	ink: string,
	shade: string,
	rim: number,
};

export type ImageDetails = {
	width: number | null,
	height: number | null,
	camera: string | null,
	lens: string | null,
	exposure: number | null,
	aperture: number | null,
	iso: number | null,
	focalLength: number | null,
	taken: string | null,
	location: Coordinates | null,
};

export type Item = {
	path: string,
	name: string,
	kind: Kind,
	native: boolean,
	modified: number,
	size: number,
};

export type Kind = "image" | "video" | "audio" | "document" | "font";

export type Listing = {
	folder: string,
	items: Item[],
	folders: Folder[],
};

export type Locale = {
	languages: string[],
	formats: string,
	fixed: boolean,
};

export type Location = {
	place: Place,
	path: string,
};

export type MediaAction = { action: "play" } | { action: "pause" } | { action: "toggle" } | { action: "stop" } | { action: "next" } | { action: "previous" } | { action: "seek"; value: number } | { action: "position"; value: number } | { action: "raise" } | { action: "shuffle"; value: boolean } | { action: "repeat"; value: Repeat } | { action: "volume"; value: number } | { action: "rate"; value: number };

export type Motion = "full" | "reduced" | "off";

export type Palette = {
	accent: string,
	wallpaperAccent: string,
	pureBlack: boolean,
	colors: SchemeColors,
	terminal: SchemeColors,
	appIcons: AppIcons,
	taskbar: import("@luft/ui").TaskbarLooks,
};

export type Pixels = {
	path: string,
	width: number,
	height: number,
	channels: number,
};

export type Place = "pictures" | "videos" | "music" | "documents";

export type PlaybackStatus = "Playing" | "Paused" | "Stopped";

export type Ready = {
	path: string,
	thumbnail: string | null,
	modified: number,
};

export type Repeat = "None" | "Track" | "Playlist";

export type Role = "interface" | "monospace";

export type SchemeColors = {
	light: { [key in string]: string },
	dark: { [key in string]: string },
};

export type SubtitleTrack = {
	id: string,
	label: string | null,
	language: string | null,
	path: string | null,
};

export type Tags = {
	path: string,
	title: string | null,
	artist: string | null,
	album: string | null,
	albumArtist: string | null,
	track: number | null,
	disc: number | null,
	year: number | null,
	genre: string | null,
	duration: number | null,
	art: string | null,
};

export type ThumbnailBatch = {
	items: Ready[],
};

export type ThumbnailSize = "normal" | "large" | "x-large" | "xx-large";

export type Typography = {
	interface: string | null,
	monospace: string | null,
	textScale: number,
};

export type VideoInfo = {
	video: string | null,
	audio: string | null,
	subtitles: SubtitleTrack[],
};

export type WallpaperStyle = "light" | "dark";
